"""Render prepared cases, all attempts and current evidence without hiding failures."""
import pathlib,json,re,html,datetime,os
tests=pathlib.Path(__file__).resolve().parent;root=tests/'evidence/uat-20261021'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
plan=read(root/'plan.json');cohorts=[];all_rows=[]
for suite in plan['suites']:
    source=(tests/(suite['script']+'.mjs')).read_text(encoding='utf-8')
    expected=list(dict.fromkeys(re.findall(r"(?:check|test)\(['\"]([^'\"]+)['\"]",source)))
    if suite['id']=='files':expected=['FILE_'+e+'_PRIVATE_PARSE' for e in ['TXT','PDF','DOCX','PNG','JPG']]+['FILE_REMOVE_FREES_TASK_CAPACITY_WITHOUT_RESETTING_SESSION','FILE_SUMMARY_CONTAINS_EXTRACTED_SYNTHETIC_VALUES','FILE_ASK_KNOWLEDGE_USES_PRIVATE_TASK_WITH_CITATION_AND_NO_DOM','FILE_REVIEW_REJECT_AND_NO_SAVE','FILE_END_TASK_REMOVES_PRIVATE_ACCESS']
    if suite['id']=='uploads':expected=[site+'_'+name for site in ['local','public'] for name in ['SHARED_UPLOAD_NOT_OFFERED','PRIVATE_UPLOAD_AND_SERVER_COOLDOWN','AUTHENTICATED_VISITOR_SHARED_UPLOAD_REFUSED','END_TASK_CLEAR']]
    attempts=[];latest={}
    folders=sorted(root.glob(suite['id']+'-attempt-*'),key=lambda p:int(p.name.rsplit('-',1)[1]) if p.is_dir() else -1)
    folders=[p for p in folders if p.is_dir()]
    if suite['id']=='immediate':folders=sorted((tests/'evidence/immediate-phase-20261019').glob('uat-20261021-immediate-attempt-*'))
    for folder in folders:
        path=folder/('browser-results.json' if suite['id']=='uploads' else 'results.json')
        log=root/(folder.name.removeprefix('uat-20261021-')+'.log')
        if not path.exists():attempts.append({'attempt':folder.name,'results':[],'log':os.path.relpath(log,root).replace('\\','/'),'note':'No completed case result: setup or process did not finish.'});continue
        data=read(path);rows=data if isinstance(data,list) else data.get('results',[])
        for row in rows:
            if row['id']=='UPLOAD_BROWSER_ACCEPTANCE':continue # Aggregate setup failure stays in attempts, not an extra feature case.
            case={**row,'cohort':suite['id'],'kind':suite['kind'],'evidence':os.path.relpath(path,root).replace('\\','/'),'attempt':folder.name,'website':data.get('website') if isinstance(data,dict) else None}
            latest[row['id']]=case
            if row['id'] not in expected:expected.append(row['id'])
        attempts.append({'attempt':folder.name,'results':rows,'log':os.path.relpath(log,root).replace('\\','/')})
    cases=[latest.get(id,{'id':id,'cohort':suite['id'],'kind':suite['kind'],'status':'blocked','detail':'Awaiting executable prerequisite or case execution; not counted as a pass.'}) for id in expected]
    all_rows+=cases;cohorts.append({**suite,'cases':cases,'attempts':attempts})
admin=root/'admin-live/results.json'
if admin.exists():
    rows=read(admin)['results'];all_rows+=[{**r,'cohort':'admin-live','kind':'live-admin','evidence':'admin-live/results.json'} for r in rows]
counts={status:sum(r['status']==status for r in all_rows) for status in ['passed','failed','partial','blocked']}
executed=counts['passed']+counts['failed']+counts['partial'];rate=100*counts['passed']/executed if executed else 0
ready=counts['blocked']==0 and counts['failed']==0 and rate>=98
summary={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'build':'20261021-uat-j','targetPercent':98,'counts':counts,'executedPassPercent':rate,'allPlannedExecutableCasesComplete':counts['blocked']==0,'gatePassed':ready,'note':'Unit checks are separate; missing/blocked cases cannot disappear from the completeness gate. Historical failures remain in attempts. A current successful synthetic adapter case is not proof of LLM behavior or fresh-owner DNS onboarding.','cohorts':cohorts,'cases':all_rows,'deferred':plan['deferred']}
(root/'report.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False),encoding='utf-8')
esc=lambda x:html.escape(str(x));link=lambda p,label:f'<a href="{esc(p)}">{esc(label)}</a>'
overview=''.join('<tr><td>'+esc(c['id'])+'</td><td>'+esc(c['kind'])+'</td>'+''.join('<td>'+str(sum(r['status']==state for r in c['cases']))+'</td>' for state in ['passed','failed','partial','blocked'])+'</tr>' for c in cohorts)
admin_overview='<tr><td>Signed-in Admin / workflow</td><td>live-admin</td>'+''.join('<td>'+str(sum(r['cohort']=='admin-live' and r['status']==state for r in all_rows))+'</td>' for state in ['passed','failed','partial','blocked'])+'</tr>'
rows=''.join('<tr><td>'+esc(r['cohort'])+'</td><td>'+esc(r['id'])+'</td><td class="'+esc(r['status'])+'">'+esc(r['status'])+'</td><td>'+esc(r.get('error') or r.get('detail',''))[:1600]+'</td><td>'+(link(r['evidence'],'Evidence') if r.get('evidence') else 'Pending')+'</td></tr>' for r in all_rows)
history=''.join('<li>'+esc(a['attempt'])+': '+str(sum(x.get('status')=='passed' for x in a['results']))+' passed / '+str(sum(x.get('status')=='failed' for x in a['results']))+' failed. '+(link(a['log'],'Log') if (root/a['log']).exists() else '')+'</li>' for s in cohorts for a in s['attempts'])
service=''
for filename in ['service-tests.log','linux-tests-j.log']:
    p=root/filename
    if p.exists():
        text=p.read_text(encoding='utf-8-sig',errors='replace');passed=re.findall(r'^# pass (\d+)',text,re.M);failed=re.findall(r'^# fail (\d+)',text,re.M)
        if passed:service+='<li>'+link(filename,filename)+': '+passed[-1]+' passed, '+(failed[-1] if failed else '?')+' failed. Repeated service cohorts are not added to browser counts.</li>'
gallery=''.join('<figure>'+link(str(p.relative_to(root)),f'<img loading="lazy" src="{p.relative_to(root)}">')+'</figure>' for p in [])
selected=[]
for folder in ['workflow-live','files-attempt-6','choices-attempt-3','complex-attempt-10','multisite-attempt-3','admin-live']:
    selected+=list((root/folder).glob('*.png'))[:2]
gallery=''.join(f'<figure><a href="{p.relative_to(root)}"><img loading="lazy" src="{p.relative_to(root)}" alt="{esc(p.stem)}"></a><figcaption>{esc(p.stem)}</figcaption></figure>' for p in selected)
document=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Digital Adoption UAT · 21–22 October 2026</title><style>body{{margin:0;background:#f5f7fa;color:#172c43;font:15px/1.55 system-ui}}main{{max-width:1300px;margin:auto;padding:28px}}header,section{{background:white;padding:22px;border:1px solid #dae0e7;border-radius:12px;margin:16px 0}}h1{{font-size:30px;line-height:1.2}}a{{color:#075c9d}}table{{width:100%;border-collapse:collapse}}td,th{{padding:10px;text-align:left;border-bottom:1px solid #dae0e7;vertical-align:top}}td:nth-child(4){{max-width:450px;white-space:pre-wrap;overflow-wrap:anywhere}}.scroll{{overflow:auto}}.passed{{color:#096b49}}.failed{{color:#b3261e}}.blocked,.partial{{color:#875b00}}.score{{font-size:24px;font-weight:650}}.gallery{{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}}figure{{margin:0}}img{{width:100%}}figcaption{{padding:8px}}</style><main><header><h1>Digital Adoption: tester acceptance and regression</h1><p>Prepared case matrix, loopback + public Flolah preview, synthetic transactions, isolated Chrome. Live admin uses the user-authorized account. Last evidence reconciliation: {esc(summary['at'])} UTC.</p><p class="score">{counts['passed']} passed · {counts['failed']} failed · {counts['partial']} partial · {counts['blocked']} blocked</p><p>{rate:.2f}% of executed cases passed. <strong>98% completion gate: {'PASSED' if ready else 'NOT YET MET'}</strong>. Blocked or unexecuted planned cases prevent certification. Service/unit totals do not inflate this percentage.</p><p>{link('plan.json','Prepared scope and case cohorts')} · {link('report.json','Machine-readable results')} · {link('deployment-j.log','Deployment verification')}</p></header><section><h2>Fixes and recommendations</h2><ul><li>Restored the loopback-only fixture and issued the explicitly approved seven-day installation through authenticated management, restricted to 127.0.0.1:4194. The API validates lifetime and the UI shows exact expiry. No backend knowledge or record seeding was used in these tests; existing registrations, knowledge and owner-reviewed bindings were reused.</li><li>Upload notice now distinguishes the effective four-file active-task capacity from the 20-file rolling session allowance. Quotas and permissions were preserved; remove an unneeded file before adding another.</li><li>Summarize files now opens Chat with the supporting passages. A browser regression verifies that the result becomes visible, rather than remaining in hidden chat history.</li><li>Setup readiness now says its map observation must be within 24 hours. Older stored maps remain accessible.</li><li>Test harness corrections: wait for initialized controls and actual failed-request completion, bring the intended tab forward, and observe animation dispatch rather than sampling an already-finished animation. First failures remain below.</li><li>Live Admin website/map/teaching/group/analytics views were checked without changing policies. Run 4067 refused an offline target. Runs 4068 and 4069 completed local read-only inspection through the real Flolah engine; 4069 reused the saved group after coordinator restart without relinking. Recipient screenshots and chat/activity traces are retained. Live autonomous workflow filling/Saves were not re-granted: current reviewed browser multi-form Saves and isolated workflow execution are separately evidenced.</li><li>Guide mode now converts edit intent with fill actions into read-only guidance consistently. Literal quoted values exclude later explanatory prose; exact source quotations get bounded verbatim repair examples. Goal review distinguishes ordinary consent UI and immediately completable validation from genuinely missing facts, which require a question and no waiting step. Provider goal schemas now require the nonempty text enforced by the parser, with specific repair diagnostics. Model route, 2,048-token budget, Action Policies and native Save review remain unchanged. Explicit approvals and independent readback are required for synthetic host Saves.</li></ul></section><section><h2>Results by feature cohort</h2><div class="scroll"><table><tr><th>Feature</th><th>Evidence type</th><th>Passed</th><th>Failed</th><th>Partial</th><th>Blocked</th></tr>{overview}{admin_overview}</table></div><p>Current status uses the latest completed result for each prepared feature case. Earlier failed attempts remain below. Aggregate harness/setup errors are retained with their attempt and do not become extra feature cases.</p></section><section><h2>Case-by-case current results</h2><div class="scroll"><table><tr><th>Cohort</th><th>Test case</th><th>Status</th><th>Outcome or failure</th><th>Evidence</th></tr>{rows}</table></div></section><section><h2>Service and operational regression</h2><ul>{service}<li>{link('private-capacity.log','25-website/25-user isolated coordination benchmark')}: simulated loopback model/commands, real text parsing. No production LLM throughput claim.</li></ul></section><section><h2>Performance and limits</h2><p>Fresh 60-second samples on both approved websites: enabled renderer JavaScript heap ended at 3.0–3.8 MiB, renderer CPU under 0.07% of one core, 2–6 idle HTTP requests/minute. This is JS heap, not total browser RSS, and does not prove long-term leak freedom. A coordinator rollout occurred during the overall measurement window; short reconnect traffic can be included.</p><p>{link('performance/results.json','Baseline and enabled renderer measurements')} · {link('private-capacity.log','25-site/25-user coordination benchmark')}</p><p>Real Safari/iOS, Android and screen-reader checks remain user-deferred. Real fresh-owner inbox/DNS verification and interactive capture are separately qualified below. Do not call these browser/device cases partial passes.</p></section><section><h2>Screenshots</h2><div class="gallery">{gallery}</div></section><section><h2>All retained attempts</h2><ul>{history}</ul><h2>Deferred or separately qualified scope</h2><ul>{''.join('<li>'+esc(x)+'</li>' for x in plan['deferred'])}</ul><p>Existing registrations cannot prove fresh-owner real DNS/email onboarding. Synthetic capture is not proof of real screen-share permission. No full Phase 1/2 certification is claimed from this matrix.</p></section></main></html>'''
(root/'index.html').write_text(document,encoding='utf-8')
umbrella=tests/'evidence/goal-plans-20261020/index.html';s=umbrella.read_text(encoding='utf-8');s=re.sub(r'<section class="card" id="uat-20261021">.*?</section>','',s,flags=re.S);notice='<section class="card" id="uat-20261021"><h1>21–22 October: visitor UAT acceptance and regression</h1><p>'+link('../uat-20261021/index.html','Open current case matrix, all failures and retests')+'</p><p>'+esc(str(counts))+' · completion gate '+('passed' if ready else 'not yet met')+'. Earlier reports below retain their original scope and dates; this is a finite scoped acceptance matrix, not a statistical reliability guarantee.</p></section>';s=s.replace('<main>','<main>'+notice,1);umbrella.write_text(s,encoding='utf-8')
print(json.dumps({**counts,'executedPassPercent':rate,'gatePassed':ready}))
